def clean(df):
    df = df[df['species'] == 'Adelie'].copy()
    df['island'] = df['island'].replace({'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'})
    return df

def answer(df):
    clean_df = clean(df)
    grouped = clean_df.groupby('island')['bill_length_mm'].mean()
    return {k: v for k, v in grouped.items()}
